"""MCP tools for scheduling GitHub observations and reading summaries."""

from mcp.server.fastmcp import FastMCP
from scheduler import Scheduler

mcp = FastMCP("Bublik Day 18 Scheduler")
scheduler = Scheduler()


@mcp.tool()
def schedule_github_summary(owner: str, repo: str, interval_minutes: int = 60) -> dict:
    """Schedule recurring GitHub repository snapshots; first snapshot is due immediately.

    Args:
        owner: GitHub repository owner.
        repo: GitHub repository name.
        interval_minutes: Period in minutes, from 1 to 10080.
    """
    return scheduler.schedule(owner, repo, interval_minutes)


@mcp.tool()
def get_github_summary(owner: str, repo: str, limit: int = 20) -> dict:
    """Return saved observations and change since the oldest selected observation.

    Args:
        owner: GitHub repository owner.
        repo: GitHub repository name.
        limit: Number of recent snapshots to aggregate, from 1 to 100.
    """
    return scheduler.summary(owner, repo, limit)


@mcp.tool()
def list_scheduled_jobs() -> list[dict]:
    """List persisted schedules, including next execution and latest error."""
    return scheduler.jobs()


if __name__ == "__main__":
    mcp.run(transport="stdio")

"""Manual MCP smoke test without an LLM or a Groq API key."""
import argparse
import asyncio
import json

from mcp_client import connect_mcp


async def main():
    parser = argparse.ArgumentParser(description="Call the Day 18 tools over MCP stdio")
    commands = parser.add_subparsers(dest="command", required=True)
    create = commands.add_parser("schedule", help="Create or update a recurring observation")
    create.add_argument("owner")
    create.add_argument("repo")
    create.add_argument("interval_minutes", type=int)
    commands.add_parser("jobs", help="List saved jobs")
    summary = commands.add_parser("summary", help="Read the aggregate saved result")
    summary.add_argument("owner")
    summary.add_argument("repo")
    summary.add_argument("--limit", type=int, default=20)
    args = parser.parse_args()

    if args.command == "schedule":
        name = "schedule_github_summary"
        arguments = {"owner": args.owner, "repo": args.repo,
                     "interval_minutes": args.interval_minutes}
    elif args.command == "jobs":
        name, arguments = "list_scheduled_jobs", {}
    else:
        name = "get_github_summary"
        arguments = {"owner": args.owner, "repo": args.repo, "limit": args.limit}

    async with connect_mcp() as session:
        response = await session.call_tool(name, arguments=arguments)
        for item in response.content:
            if item.type == "text":
                try:
                    print(json.dumps(json.loads(item.text), ensure_ascii=False, indent=2))
                except json.JSONDecodeError:
                    print(item.text)
        if response.isError:
            raise SystemExit(1)


if __name__ == "__main__":
    asyncio.run(main())

